];import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import type { Activity, Status } from './types';

export const DEFAULT_DASHBOARD_TITLE = '2026 재해복구 모의훈련 대시보드';
export const MAX_ACTIVITY_FILE_SIZE = 2 * 1024 * 1024;
export const MAX_ACTIVITY_COUNT = 5_000;

const ACTIVITY_FILE_PATH = process.env.ACTIVITY_DATA_FILE
  ? path.resolve(process.env.ACTIVITY_DATA_FILE)
  : path.join(process.cwd(), 'data', 'activity.json');
const activityPathParts = path.parse(ACTIVITY_FILE_PATH);
const ACTIVITY_BACKUP_PATH = path.join(
  activityPathParts.dir,
  `${activityPathParts.name}.backup${activityPathParts.ext || '.json'}`,
);
const VALID_STATUSES = new Set<Status>(['대기', '진행', '완료', '지연']);
const MAX_VALIDATION_ISSUES = 50;

export interface ActivityData {
  activities: Activity[];
  dashboardTitle: string;
  lastUpdated: string;
  visitorCount: number;
}

export interface ImportValidationIssue {
  path: string;
  message: string;
}

export interface ValidatedActivityImport {
  activities: Activity[];
  dashboardTitle?: string;
  normalizedLegacyStatuses: number;
}

export class ActivityImportValidationError extends Error {
  issues: ImportValidationIssue[];

  constructor(issues: ImportValidationIssue[]) {
    super('activity.json 데이터 형식이 올바르지 않습니다.');
    this.name = 'ActivityImportValidationError';
    this.issues = issues;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isFileNotFound(error: unknown) {
  return isRecord(error) && error.code === 'ENOENT';
}

function createInitialData(): ActivityData {
  return {
    activities: [],
    dashboardTitle: DEFAULT_DASHBOARD_TITLE,
    visitorCount: 0,
    lastUpdated: new Date().toISOString(),
  };
}

function normalizeStoredData(value: unknown): ActivityData {
  if (!isRecord(value)) {
    throw new Error('저장된 activity.json의 최상위 값이 객체가 아닙니다.');
  }

  return {
    activities: Array.isArray(value.activities) ? value.activities as Activity[] : [],
    dashboardTitle: typeof value.dashboardTitle === 'string' && value.dashboardTitle.trim()
      ? value.dashboardTitle.trim()
      : DEFAULT_DASHBOARD_TITLE,
    visitorCount: typeof value.visitorCount === 'number' && Number.isFinite(value.visitorCount)
      ? Math.max(0, Math.trunc(value.visitorCount))
      : 0,
    lastUpdated: typeof value.lastUpdated === 'string'
      ? value.lastUpdated
      : new Date().toISOString(),
  };
}

export async function readActivityData(): Promise<ActivityData> {
  try {
    const fileContent = await fs.readFile(ACTIVITY_FILE_PATH, 'utf-8');
    return normalizeStoredData(JSON.parse(fileContent));
  } catch (error) {
    if (!isFileNotFound(error)) throw error;

    const initialData = createInitialData();
    await writeActivityData(initialData);
    return initialData;
  }
}

export async function writeActivityData(data: ActivityData, options?: { createBackup?: boolean }) {
  const directory = path.dirname(ACTIVITY_FILE_PATH);
  const temporaryPath = `${ACTIVITY_FILE_PATH}.${process.pid}.${randomUUID()}.tmp`;

  await fs.mkdir(directory, { recursive: true });

  if (options?.createBackup) {
    try {
      await fs.copyFile(ACTIVITY_FILE_PATH, ACTIVITY_BACKUP_PATH);
    } catch (error) {
      if (!isFileNotFound(error)) throw error;
    }
  }

  try {
    await fs.writeFile(temporaryPath, JSON.stringify(data, null, 2), 'utf-8');
    await fs.rename(temporaryPath, ACTIVITY_FILE_PATH);
  } finally {
    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
  }
}

export function validateActivityImport(value: unknown): ValidatedActivityImport {
  const issues: ImportValidationIssue[] = [];
  let omittedIssueCount = 0;
  let normalizedLegacyStatuses = 0;

  const addIssue = (issuePath: string, message: string) => {
    if (issues.length < MAX_VALIDATION_ISSUES) {
      issues.push({ path: issuePath, message });
    } else {
      omittedIssueCount += 1;
    }
  };

  if (!isRecord(value)) {
    throw new ActivityImportValidationError([
      { path: '$', message: '최상위 값은 activities 배열을 포함한 JSON 객체여야 합니다.' },
    ]);
  }

  if (!Array.isArray(value.activities)) {
    throw new ActivityImportValidationError([
      { path: 'activities', message: 'activities 필드는 배열이어야 합니다.' },
    ]);
  }

  if (value.activities.length > MAX_ACTIVITY_COUNT) {
    addIssue('activities', `액티비티는 최대 ${MAX_ACTIVITY_COUNT.toLocaleString('ko-KR')}개까지 업로드할 수 있습니다.`);
  }

  let dashboardTitle: string | undefined;
  if (value.dashboardTitle !== undefined) {
    if (typeof value.dashboardTitle !== 'string' || !value.dashboardTitle.trim()) {
      addIssue('dashboardTitle', 'dashboardTitle은 비어 있지 않은 문자열이어야 합니다.');
    } else if (value.dashboardTitle.trim().length > 100) {
      addIssue('dashboardTitle', 'dashboardTitle은 100자 이하여야 합니다.');
    } else {
      dashboardTitle = value.dashboardTitle.trim();
    }
  }

  const candidates: Array<{ activity: Activity; index: number } | null> = value.activities.map((rawActivity, index) => {
    const basePath = `activities[${index}]`;
    if (!isRecord(rawActivity)) {
      addIssue(basePath, '각 액티비티는 객체여야 합니다.');
      return null;
    }

    let valid = true;

    const id = rawActivity.id;
    if (typeof id !== 'string' || !id.trim()) {
      addIssue(`${basePath}.id`, 'id는 비어 있지 않은 문자열이어야 합니다.');
      valid = false;
    } else if (id.length > 120) {
      addIssue(`${basePath}.id`, 'id는 120자 이하여야 합니다.');
      valid = false;
    }

    const parentId = rawActivity.parentId;
    if (parentId !== null && (typeof parentId !== 'string' || !parentId.trim())) {
      addIssue(`${basePath}.parentId`, 'parentId는 null 또는 비어 있지 않은 문자열이어야 합니다.');
      valid = false;
    }

    const level = rawActivity.level;
    if (!Number.isInteger(level) || (level as number) < 1 || (level as number) > 50) {
      addIssue(`${basePath}.level`, 'level은 1 이상 50 이하의 정수여야 합니다.');
      valid = false;
    }

    const time = rawActivity.time;
    if (typeof time !== 'string' || !time.trim()) {
      addIssue(`${basePath}.time`, 'time은 비어 있지 않은 문자열이어야 합니다.');
      valid = false;
    } else if (time.length > 100) {
      addIssue(`${basePath}.time`, 'time은 100자 이하여야 합니다.');
      valid = false;
    }

    const title = rawActivity.title;
    if (typeof title !== 'string' || !title.trim()) {
      addIssue(`${basePath}.title`, 'title은 비어 있지 않은 문자열이어야 합니다.');
      valid = false;
    } else if (title.length > 300) {
      addIssue(`${basePath}.title`, 'title은 300자 이하여야 합니다.');
      valid = false;
    }

    let status = rawActivity.status;
    if (status === '진행중') {
      status = '진행';
      normalizedLegacyStatuses += 1;
    }
    if (typeof status !== 'string' || !VALID_STATUSES.has(status as Status)) {
      addIssue(`${basePath}.status`, 'status는 대기, 진행, 지연, 완료 중 하나여야 합니다.');
      valid = false;
    }

    if (!valid) return null;

    return {
      index,
      activity: {
        id: (id as string).trim(),
        parentId: parentId === null ? null : (parentId as string).trim(),
        level: level as number,
        time: time as string,
        title: title as string,
        status: status as Status,
      },
    };
  });

  const validCandidates = candidates.filter((candidate): candidate is NonNullable<typeof candidate> => candidate !== null);
  const activityById = new Map<string, { activity: Activity; index: number }>();

  for (const candidate of validCandidates) {
    const existing = activityById.get(candidate.activity.id);
    if (existing) {
      addIssue(
        `activities[${candidate.index}].id`,
        `id "${candidate.activity.id}"가 activities[${existing.index}]와 중복됩니다.`,
      );
    } else {
      activityById.set(candidate.activity.id, candidate);
    }
  }

  for (const candidate of validCandidates) {
    const { activity, index } = candidate;
    if (activity.parentId === null) {
      if (activity.level !== 1) {
        addIssue(`activities[${index}].level`, '최상위 액티비티(parentId: null)의 level은 1이어야 합니다.');
      }
      continue;
    }

    if (activity.parentId === activity.id) {
      addIssue(`activities[${index}].parentId`, '자기 자신을 부모로 지정할 수 없습니다.');
      continue;
    }

    const parent = activityById.get(activity.parentId);
    if (!parent) {
      addIssue(`activities[${index}].parentId`, `부모 id "${activity.parentId}"가 activities에 존재하지 않습니다.`);
    } else if (activity.level !== parent.activity.level + 1) {
      addIssue(
        `activities[${index}].level`,
        `부모 "${activity.parentId}"의 level(${parent.activity.level})보다 정확히 1 커야 합니다.`,
      );
    }
  }

  const visitState = new Map<string, 'visiting' | 'visited'>();
  const reportedCycles = new Set<string>();

  const visit = (candidate: { activity: Activity; index: number }, chain: string[]) => {
    const id = candidate.activity.id;
    const state = visitState.get(id);
    if (state === 'visited') return;
    if (state === 'visiting') {
      const cycleStart = chain.indexOf(id);
      const cycle = [...chain.slice(Math.max(0, cycleStart)), id];
      const cycleKey = [...new Set(cycle)].sort().join('|');
      if (!reportedCycles.has(cycleKey)) {
        reportedCycles.add(cycleKey);
        addIssue(`activities[${candidate.index}].parentId`, `부모 관계가 순환합니다: ${cycle.join(' → ')}`);
      }
      return;
    }

    visitState.set(id, 'visiting');
    if (candidate.activity.parentId) {
      const parent = activityById.get(candidate.activity.parentId);
      if (parent) visit(parent, [...chain, id]);
    }
    visitState.set(id, 'visited');
  };

  for (const candidate of validCandidates) visit(candidate, []);

  if (omittedIssueCount > 0) {
    issues.push({
      path: '$',
      message: `오류가 너무 많아 ${omittedIssueCount.toLocaleString('ko-KR')}개 항목은 생략했습니다. 먼저 표시된 오류를 수정한 뒤 다시 시도해 주세요.`,
    });
  }

  if (issues.length > 0) throw new ActivityImportValidationError(issues);

  return {
    activities: validCandidates.map(({ activity }) => activity),
    dashboardTitle,
    normalizedLegacyStatuses,
  };
}
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { Activity } from './types.ts';
import {
  ActivityImportValidationError,
  validateActivityImport,
  type ImportValidationIssue,
} from './activityData.ts';

// 라우트가 JSON.parse 로 만들어 넘기는 것과 같은 평문 객체를 그대로 쓴다(모킹 없음).
function raw(overrides: Partial<Record<keyof Activity, unknown>>): Record<string, unknown> {
  return { id: 'a', parentId: null, level: 1, time: '09:00', title: '작업', status: '대기', ...overrides };
}

function issuesOf(value: unknown): ImportValidationIssue[] {
  try {
    validateActivityImport(value);
  } catch (error) {
    if (!(error instanceof ActivityImportValidationError)) throw error;
    return error.issues;
  }
  return assert.fail('ActivityImportValidationError 가 발생해야 합니다.');
}

describe('validateActivityImport 정상 입력', () => {
  it('최상위와 자식 2건을 통과시키고 id·parentId 의 앞뒤 공백을 trim 한다', () => {
    const result = validateActivityImport({
      activities: [
        raw({ id: '  root  ', parentId: null, level: 1 }),
        raw({ id: '  child  ', parentId: '  root  ', level: 2 }),
      ],
    });

    assert.equal(result.activities.length, 2);
    assert.deepEqual(result.activities.map((activity) => activity.id), ['root', 'child']);
    assert.equal(result.activities[1].parentId, 'root');
  });

  it('dashboardTitle 의 앞뒤 공백을 trim 해서 돌려준다', () => {
    const result = validateActivityImport({
      activities: [raw({})],
      dashboardTitle: '  제목  ',
    });

    assert.equal(result.dashboardTitle, '제목');
  });

  it('dashboardTitle 을 주지 않으면 undefined 를 돌려준다', () => {
    const result = validateActivityImport({ activities: [raw({})] });

    assert.equal(result.dashboardTitle, undefined);
  });

  it('빈 activities 배열은 throw 하지 않고 빈 배열을 돌려준다', () => {
    // 관리 화면의 "최상위 작업 추가" 진입점이 이 계약에 의존한다.
    const result = validateActivityImport({ activities: [] });

    assert.deepEqual(result.activities, []);
  });
});

describe('validateActivityImport 최상위 형식 오류', () => {
  for (const [label, value] of [
    ['배열', [] as unknown],
    ['문자열', 'x' as unknown],
    ['null', null as unknown],
  ] as const) {
    it(`최상위 값이 객체가 아니면(${label}) path '$' 오류 1건으로 throw 한다`, () => {
      const issues = issuesOf(value);

      assert.equal(issues.length, 1);
      assert.equal(issues[0].path, '$');
    });
  }

  it("activities 가 배열이 아니면 path 'activities' 오류 1건으로 throw 한다", () => {
    const issues = issuesOf({ activities: 'x' });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities');
  });
});

describe('validateActivityImport 관계 오류의 issues[].path', () => {
  it('id 가 중복되면 뒤쪽 항목의 id 경로를 가리키고 메시지에 앞쪽 인덱스를 담는다', () => {
    const issues = issuesOf({ activities: [raw({ id: 'a' }), raw({ id: 'a' })] });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities[1].id');
    assert.match(issues[0].message, /activities\[0\]/);
  });

  it('부모가 존재하지 않으면 parentId 경로를 가리킨다', () => {
    const issues = issuesOf({ activities: [raw({ id: 'a', parentId: 'ghost', level: 2 })] });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities[0].parentId');
  });

  it('부모 level 보다 정확히 1 크지 않으면 자식의 level 경로를 가리킨다', () => {
    const issues = issuesOf({
      activities: [raw({ id: 'root', parentId: null, level: 1 }), raw({ id: 'child', parentId: 'root', level: 3 })],
    });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities[1].level');
  });

  it('자기 자신을 부모로 지정하면 parentId 경로로 자기참조·순환 2건이 난다', () => {
    // 부모 부재·level 검사는 continue 로 건너뛰지만, 순환 검사는 별도 패스라 a → a 를 순환으로도 잡는다.
    const issues = issuesOf({ activities: [raw({ id: 'a', parentId: 'a', level: 1 })] });

    assert.deepEqual(issues.map((issue) => issue.path), ['activities[0].parentId', 'activities[0].parentId']);
    assert.match(issues[0].message, /자기 자신을 부모/);
    assert.match(issues[1].message, /순환/);
  });

  it('최상위인데 level 이 1 이 아니면 level 경로를 가리킨다', () => {
    const issues = issuesOf({ activities: [raw({ id: 'a', parentId: null, level: 2 })] });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities[0].level');
  });

  it('두 항목이 서로를 부모로 가리키면 순환 오류는 1건만 난다', () => {
    // a↔b 는 어떤 level 조합으로도 부모-level 규칙을 만족할 수 없어 level 오류가 함께 난다.
    const issues = issuesOf({
      activities: [raw({ id: 'a', parentId: 'b', level: 2 }), raw({ id: 'b', parentId: 'a', level: 3 })],
    });

    const cycleIssues = issues.filter((issue) => issue.message.includes('순환'));
    assert.equal(cycleIssues.length, 1);
    assert.equal(cycleIssues[0].path, 'activities[0].parentId');
  });
});

describe("validateActivityImport 의 '진행중' 정규화", () => {
  it("status '진행중' 을 '진행' 으로 바꾸고 변환 건수를 세어 돌려준다", () => {
    const result = validateActivityImport({
      activities: [
        raw({ id: 'root', parentId: null, level: 1, status: '진행중' }),
        raw({ id: 'child', parentId: 'root', level: 2, status: '진행중' }),
      ],
    });

    assert.deepEqual(result.activities.map((activity) => activity.status), ['진행', '진행']);
    assert.equal(result.normalizedLegacyStatuses, 2);
  });
});

describe('validateActivityImport 의 issues 상한', () => {
  it('오류가 50건을 넘으면 50건 + 생략 안내 1건만 돌려준다', () => {
    const activities = Array.from({ length: 60 }, (_, index) => raw({ id: `a${index}`, title: '' }));

    const issues = issuesOf({ activities });

    assert.equal(issues.length, 51);
    assert.equal(issues[50].path, '$');
    assert.match(issues[50].message, /10/);
  });
});

'use client';
import { useEffect, useState } from 'react';
import useSWR from 'swr';
import ActivityTree from '@/components/ActivityTree';
import ActivityJsonImporter from '@/components/ActivityJsonImporter';
import TrackingSettings from '@/components/TrackingSettings';
import MailSettings from '@/components/MailSettings';
import { fetchActivityData } from '@/lib/fetchJson';
import { buildTree, collectDescendantIds } from '@/lib/treeUtils';
import type { ActivitiesData, Activity } from '@/lib/types';
import Cookies from 'js-cookie';
import { AlertCircle, Loader2, Edit3, Plus, Save, X } from 'lucide-react';

export default function AdminPage() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);
  const [pw, setPw] = useState('');
  const [loginError, setLoginError] = useState('');
  const { data, error: loadError, mutate } = useSWR('/api/activities', fetchActivityData, { refreshInterval: 1000 });
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [saveError, setSaveError] = useState('');

  useEffect(() => {
    let active = true;

    fetch('/api/auth/session', { cache: 'no-store' })
      .then((response) => {
        if (!active) return;
        if (response.ok) {
          Cookies.set('cutover_admin', 'true', { expires: 7, path: '/', sameSite: 'strict' });
          setLoggedIn(true);
        } else {
          Cookies.remove('cutover_admin', { path: '/' });
          setLoggedIn(false);
        }
      })
      .catch(() => {
        if (active) setLoggedIn(false);
      })
      .finally(() => {
        if (active) setAuthChecked(true);
      });

    return () => { active = false; };
  }, []);

  const login = async () => {
    setLoginError('');
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pw, role: 'admin' })
    });
    if (res.ok) {
      Cookies.set('cutover_admin', 'true', { expires: 7, path: '/', sameSite: 'strict' });
      setLoggedIn(true);
      setPw('');
    } else {
      const result = await res.json().catch(() => null) as { error?: string } | null;
      setLoginError(result?.error ?? '관리자 비밀번호가 틀렸습니다.');
    }
  };

  const handleUnauthorized = () => {
    Cookies.remove('cutover_admin', { path: '/' });
    setLoggedIn(false);
    setSaveError('');
    setLoginError('관리자 인증이 만료되었습니다. 다시 로그인해 주세요.');
  };

  /**
   * 활동 변경 PUT 한 곳. 응답을 반드시 읽어 실패면 화면에 남긴다.
   * SWR 1초 폴링이 실패한 값을 조용히 되돌리므로, 성공 여부는 이 응답으로만 판단한다.
   */
  const submitActivityChange = async (body: Record<string, unknown>): Promise<boolean> => {
    try {
      const res = await fetch('/api/activities', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const result = await res.json().catch(() => null) as { error?: string } | null;
        if (res.status === 401) {
          handleUnauthorized();
          return false;
        }
        setSaveError(result?.error ?? `변경 사항을 저장하지 못했습니다. (HTTP ${res.status})`);
        return false;
      }

      setSaveError('');
      // 성공한 PUT 은 새 lastUpdated 를 포함한 완전한 ActivitiesData 를 돌려준다. 그것을 그대로
      // 캐시에 넣어야 내 쓰기만큼 스냅샷이 전진한다 — GET 이 실패하는 동안 재요청만 하면 스냅샷이
      // 첫 로드에 멈춰, 혼자 일하는데도 두 번째 저장부터 전부 409(STALE_SNAPSHOT)로 막힌다.
      const result = await res.json().catch(() => null) as ActivitiesData | null;
      if (result) void mutate(result, { revalidate: false });
      else void mutate();
      return true;
    } catch (error) {
      setSaveError(
        `서버에 연결하지 못해 변경 사항을 저장하지 못했습니다. (${error instanceof Error ? error.message : '알 수 없는 네트워크 오류'})`,
      );
      return false;
    }
  };

  const saveDashboardTitle = async () => {
    // 저장이 성공했을 때만 편집을 닫는다. 실패하면 입력한 제목이 그대로 남는다.
    if (await submitActivityChange({ dashboardTitle: editTitle })) setIsEditingTitle(false);
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-[#0A2A66] flex items-center justify-center text-white">
        <Loader2 size={32} className="animate-spin" aria-label="관리자 인증 확인 중" />
      </div>
    );
  }

  if (!loggedIn) {
    return (
      <div className="min-h-screen bg-[#0A2A66] flex items-center justify-center p-6">
        <div className="w-full max-w-[400px] bg-white rounded-3xl p-10 shadow-2xl">
          <div className="text-center mb-10">
            <div className="text-[#EF4444] text-3xl font-bold mb-2 tracking-tight">Korea Credit Bureau.</div>
            <div className="text-2xl font-semibold text-gray-800">Dashboard Admin</div>
            <div className="text-sm text-gray-500 mt-1">관리자 페이지</div>
          </div>

          <input
            type="password"
            placeholder="관리자 비밀번호"
            value={pw}
            onChange={e => setPw(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') void login(); }}
            className="w-full border border-gray-300 rounded-2xl px-6 py-5 text-lg focus:outline-none focus:border-[#0A4B9E]"
          />

          {loginError && <p role="alert" className="mt-3 text-sm text-red-600">{loginError}</p>}

          <button 
            onClick={login} 
            className="mt-6 w-full bg-[#0A4B9E] hover:bg-[#083A7A] py-5 rounded-2xl text-xl font-semibold text-white transition"
          >
            로그인
          </button>
        </div>
      </div>
    );
  }

  const tree = data ? buildTree(data.activities) : [];

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 pb-24">
      <div className="max-w-2xl mx-auto px-5 pt-8">
        <div className="flex justify-between items-center mb-8">
              </div>
              <button
                onClick={() => {
                  setEditTitle(data?.dashboardTitle || '2026 재해복구 모의훈련 대시보드');
                  setIsEditingTitle(true);
                }}
                className="text-gray-400 hover:text-blue-600 p-2"
                title="제목 수정"
              >
                <Edit3 size={18} />
              </button>
            </div>
          )}
        </div>

        <ActivityJsonImporter
          currentData={data as ActivitiesData | undefined}
          onImported={(importedData) => {
            void mutate(importedData, { revalidate: false });
          }}
          onUnauthorized={handleUnauthorized}
        />

        <TrackingSettings onUnauthorized={handleUnauthorized} />

        <MailSettings onUnauthorized={handleUnauthorized} />

        {/* Admin 범례 (진행중 → 진행으로 수정) */}
        <div className="flex gap-6 text-sm mb-6 bg-white p-4 rounded-2xl shadow">
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-blue-600"></div>
            <span>완료</span>
          </div>
          <div className="flex items-center gap-2">
            <Loader2 size={16} className="animate-spin text-orange-500" />
            <span>진행</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full border-2 border-red-500 bg-transparent"></div>
            <span>지연</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-gray-400"></div>
            <span>대기</span>
          </div>
        </div>

        <div className="space-y-1 bg-white rounded-3xl shadow-sm p-2">
          {tree.length === 0 && (
            <div data-testid="empty-activity-tree" className="px-4 py-8 text-center text-sm text-gray-500">
              등록된 작업이 없습니다. 아래 버튼으로 첫 작업을 추가하거나 `activity.json` 을 업로드하십시오.
            </div>
          )}

          {tree.map(node => (
            <ActivityTree 
              key={node.id} 
              node={node} 
              forceCollapsed={false}
              isAdmin={true}
              onStatusChange={async (id, newStatus) => {
                let activities = [...(data?.activities ?? [])];

                // 대상과 모든 하위(parentId 관계)를 같은 상태로
                const affected = collectDescendantIds(activities, id);
                activities = activities.map((a: Activity) => {
                  if (affected.has(a.id)) {
                    return { ...a, status: newStatus };
                  }
                  return a;
                });

                // 부모 자동 진행 처리
                if (newStatus === '대기' || newStatus === '진행') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    activities = activities.map((a: Activity) => {
                      if (a.id === target.parentId) {
                        return { ...a, status: '진행' };
                      }
                      return a;
                    });
                  }
                }

                // 자식 모두 완료 시 부모 완료
                if (newStatus === '완료') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    const siblings = activities.filter((a: Activity) => a.parentId === target.parentId);
                    if (siblings.every((a: Activity) => a.status === '완료')) {
                      activities = activities.map((a: Activity) => {
                        if (a.id === target.parentId) {
                          return { ...a, status: '완료' };
                        }
                        return a;
                      });
                    }
                  }
                }

                // 스냅샷 시점을 함께 보낸다. 그 사이 다른 관리자가 바꿨으면 서버가 409 로 막는다.
                await submitActivityChange({
                  activities,
                  targetId: id,
                  newStatus,
                  ...(data ? { expectedLastUpdated: data.lastUpdated } : {}),
                });
              }}
              onUpdateActivity={async (id, updated) => {
                const newActivities = (data?.activities ?? []).map((a: Activity) =>
                  a.id === id ? { ...a, ...updated } : a
                );
                return submitActivityChange({
                  activities: newActivities,
                  targetId: id,
                  ...(data ? { expectedLastUpdated: data.lastUpdated } : {}),
                });
              }}
              onDeleteActivity={async (id) => {
                // 확인창은 ActivityTree 의 삭제 버튼에서 한 번만 띄운다(그쪽이 지우는 노드를 안다).
                await submitActivityChange({ action: 'delete', targetId: id });
              }}
              onMoveActivity={async (id, direction) => {
                await submitActivityChange({ action: 'move', targetId: id, direction });
              }}
              onAddActivity={async (parentId) => {
                await submitActivityChange({ action: 'add', parentId });
              }}
            />
          ))}

          {/* 트리가 비면 행 안의 추가 버튼도 함께 사라지므로, 최상위 추가는 목록 밖에 항상 둔다. */}
          <button
            data-testid="add-root-activity"
            onClick={() => { void submitActivityChange({ action: 'add', parentId: null }); }}
            className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-gray-300 px-4 py-3 text-sm font-medium text-blue-600 transition hover:border-blue-400 hover:bg-blue-50"
          >
            <Plus size={18} />
            최상위 작업 추가
          </button>
        </div>
      </div>
    </div>
  );
}
'use client';
import { useEffect, useState } from 'react';
import { 
  ChevronDown, 
  ChevronRight, 
  Loader2, 
  Edit3, 
  Save, 
  X, 
  Trash2, 
  Plus, 
  ArrowUp, 
  ArrowDown 
} from 'lucide-react';
import { Activity } from '@/lib/types';

interface Props {
  node: Activity;
  onStatusChange?: (id: string, status: Activity['status']) => void;
  /** 저장에 실패하면 false 를 돌려준다. 그때는 편집 입력을 닫지 않는다. */
  onUpdateActivity?: (id: string, updated: Partial<Activity>) => void | Promise<boolean | void>;
  onDeleteActivity?: (id: string) => void;
  onMoveActivity?: (id: string, direction: 'up' | 'down') => void;
  onAddActivity?: (parentId: string | null) => void;
  forceCollapsed?: boolean;
  isAdmin?: boolean;
}

function StatusIcon({ status }: { status: Activity['status'] }) {
  switch (status) {
    case '진행':
      return <Loader2 size={18} className="animate-spin flex-shrink-0 text-orange-500" />;
    case '완료':
      return <div className="w-4 h-4 rounded-full flex-shrink-0 bg-blue-600" />;
    case '지연':
      return <div className="w-4 h-4 rounded-full flex-shrink-0 border-2 border-red-500 bg-transparent" />;
    default:
      return <div className="w-4 h-4 rounded-full flex-shrink-0 bg-gray-400" />;
  }
}

export default function ActivityTree({ 
  node, 
  onStatusChange, 
  onUpdateActivity, 
  onDeleteActivity, 
  onMoveActivity,
  onAddActivity,
  forceCollapsed = false,
  isAdmin = false 
}: Props) {
  const [expanded, setExpanded] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({ title: node.title, time: node.time });

  const hasChildren = node.children && node.children.length > 0;
  const isRoot = node.level === 1;

  useEffect(() => {
    // 전체 펼침/접힘 버튼은 각 노드에서 사용자가 선택한 상태보다 우선합니다.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setExpanded(isAdmin || !forceCollapsed);
  }, [forceCollapsed, isAdmin]);

  const toggleExpand = () => {
    if (!isAdmin && hasChildren) {
      setExpanded(!expanded);
    }
  };

  const handleSave = async () => {
    // 저장이 실패하면(false) 편집 입력을 열어 둬 입력한 값을 잃지 않게 한다.
    if (await onUpdateActivity?.(node.id, editData) === false) return;
    setIsEditing(false);
  };

  return (
    <div className="mb-1">
      <div 
        className="border border-gray-200 bg-white rounded-2xl overflow-hidden cursor-pointer"
        onClick={toggleExpand}
      >
        <div className="flex items-center gap-3 py-2 px-3 hover:bg-gray-50 transition-all relative">
          {hasChildren && (
            <button onClick={(e) => { e.stopPropagation(); if (!isAdmin) setExpanded(!expanded); }} className="text-gray-500 hover:text-gray-900 flex-shrink-0">
              {expanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
            </button>
          )}

          <StatusIcon status={node.status} />

          <div className="flex-1 min-w-0 pr-2">
            {isEditing ? (
              <div className="space-y-1">
                <input type="text" data-testid="activity-edit-time" value={editData.time} onChange={e => setEditData({...editData, time: e.target.value})} className="w-full border border-gray-300 rounded px-2 py-0.5 text-xs" />
                <input type="text" data-testid="activity-edit-title" value={editData.title} onChange={e => setEditData({...editData, title: e.target.value})} className="w-full border border-gray-300 rounded px-2 py-1 font-medium" />
              </div>
            ) : (
              <>
                <div className="text-xs text-gray-500 font-mono tracking-tight">{node.time}</div>
                <div className="font-semibold text-gray-900 text-[15px] leading-tight break-keep">{node.title}</div>
              </>
            )}
          </div>

          {isAdmin && (
            <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
              <button onClick={() => onAddActivity?.(node.id)} className="text-blue-600 hover:text-blue-700 p-1" title="하위 추가">
                <Plus size={18} />
              </button>
              {isRoot && (
                <button onClick={() => onAddActivity?.(null)} className="text-blue-600 hover:text-blue-700 p-1" title="같은 레벨 추가">
                  <Plus size={18} />
                </button>
              )}

              <button onClick={() => onMoveActivity?.(node.id, 'up')} className="text-gray-400 hover:text-gray-700 p-1" title="위로 이동">
                <ArrowUp size={18} />
              </button>
              <button onClick={() => onMoveActivity?.(node.id, 'down')} className="text-gray-400 hover:text-gray-700 p-1" title="아래로 이동">
                <ArrowDown size={18} />
              </button>

              <button onClick={() => confirm(`"${node.title}" 및 모든 하위 액티비티를 삭제하시겠습니까?`) && onDeleteActivity?.(node.id)} className="text-red-600 hover:text-red-700 p-1" title="삭제">
                <Trash2 size={18} />
              </button>

              {isEditing ? (
                <>
                  <button onClick={() => { void handleSave(); }} className="text-emerald-600 p-1" title="편집 저장"><Save size={18} /></button>
                  <button onClick={() => {setIsEditing(false); setEditData({title: node.title, time: node.time});}} className="text-gray-500 p-1" title="편집 취소"><X size={18} /></button>
                </>
              ) : (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    // editData 는 마운트 때만 초기화되고 행은 key={node.id} 로 재사용된다.
                    // 편집을 열 때 지금 node 값을 다시 넣지 않으면, 그 사이 다른 관리자가 바꾼
                    // 제목·시간이 입력에 안 보이고 그대로 저장하면 옛 값으로 되돌아간다.
                    setEditData({ title: node.title, time: node.time });
                    setIsEditing(true);
                  }}
                  className="text-gray-500 p-1"
                  title="내용 편집"
                >
                  <Edit3 size={18} />
                </button>
              )}

              <select 
                value={node.status} 
                onChange={(e) => onStatusChange?.(node.id, e.target.value as Activity['status'])} 
                onClick={(e) => e.stopPropagation()} 
                className="bg-white border border-gray-300 rounded-xl text-sm px-3 py-1.5 text-gray-900 ml-1 cursor-pointer"
              >
                <option value="대기">대기</option>
                <option value="진행">진행</option>
                <option value="지연">지연</option>
                <option value="완료">완료</option>
              </select>
            </div>
          )}
        </div>

        {expanded && hasChildren && (
          <div className="pl-8 pr-3 pb-2 border-t border-gray-100">
            {node.children!.map((child: Activity) => (
              <ActivityTree 
                key={child.id} 
                node={child} 
                onStatusChange={onStatusChange}
                onUpdateActivity={onUpdateActivity}
                onDeleteActivity={onDeleteActivity}
                onMoveActivity={onMoveActivity}
                onAddActivity={onAddActivity}
                forceCollapsed={forceCollapsed}
                isAdmin={isAdmin} 
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
import { NextRequest, NextResponse } from 'next/server';
import {
  ActivityImportValidationError,
  MAX_ACTIVITY_FILE_SIZE,
  readActivityData,
  validateActivityImport,
  writeActivityData,
} from '@/lib/activityData';
import { isAdminRequest } from '@/lib/adminSession';

export const runtime = 'nodejs';

function errorResponse(
  status: number,
  code: string,
  error: string,
  details?: Array<{ path: string; message: string }>,
) {
  return NextResponse.json({ success: false, code, error, details }, { status });
}

function describeJsonError(error: SyntaxError, source: string) {
  const positionMatch = error.message.match(/position\s+(\d+)/i);
  if (!positionMatch) return error.message;

  const position = Number(positionMatch[1]);
  const beforeError = source.slice(0, position);
  const line = beforeError.split('\n').length;
  const lastLineBreak = beforeError.lastIndexOf('\n');
  const column = position - lastLineBreak;
  return `${line}행 ${column}열 부근의 JSON 문법을 확인해 주세요. (${error.message})`;
}

export async function POST(request: NextRequest) {
  if (!isAdminRequest(request)) {
    return errorResponse(401, 'UNAUTHORIZED', '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.');
  }

  const contentLength = Number(request.headers.get('content-length'));
  if (Number.isFinite(contentLength) && contentLength > MAX_ACTIVITY_FILE_SIZE + 64 * 1024) {
    return errorResponse(413, 'FILE_TOO_LARGE', '파일 크기는 2MB 이하여야 합니다.');
  }

  try {
    const formData = await request.formData();
    const uploadedFile = formData.get('file');

    if (!(uploadedFile instanceof File)) {
      return errorResponse(400, 'FILE_REQUIRED', '업로드할 activity.json 파일을 선택해 주세요.');
    }
    if (!uploadedFile.name.toLowerCase().endsWith('.json')) {
      return errorResponse(400, 'INVALID_FILE_TYPE', '확장자가 .json인 파일만 업로드할 수 있습니다.');
    }
    if (uploadedFile.size === 0) {
      return errorResponse(400, 'EMPTY_FILE', '선택한 파일이 비어 있습니다.');
    }
    if (uploadedFile.size > MAX_ACTIVITY_FILE_SIZE) {
      return errorResponse(413, 'FILE_TOO_LARGE', '파일 크기는 2MB 이하여야 합니다.');
    }

    const source = (await uploadedFile.text()).replace(/^\uFEFF/, '');
    let parsed: unknown;
    try {
      parsed = JSON.parse(source);
    } catch (error) {
      const message = error instanceof SyntaxError
        ? describeJsonError(error, source)
        : 'JSON 문법을 해석하지 못했습니다.';
      return errorResponse(
        400,
        'INVALID_JSON',
        'JSON 문법이 올바르지 않습니다.',
        [{ path: '$', message }],
      );
    }

    const imported = validateActivityImport(parsed);
    const currentData = await readActivityData();
    const newData = {
      activities: imported.activities,
      dashboardTitle: imported.dashboardTitle ?? currentData.dashboardTitle,
      visitorCount: currentData.visitorCount,
      lastUpdated: new Date().toISOString(),
    };

    await writeActivityData(newData, { createBackup: true });

    return NextResponse.json({
      success: true,
      importedCount: newData.activities.length,
      normalizedLegacyStatuses: imported.normalizedLegacyStatuses,
      backupCreated: true,
      data: newData,
    });
  } catch (error) {
    if (error instanceof ActivityImportValidationError) {
      return errorResponse(400, 'INVALID_SCHEMA', error.message, error.issues);
    }

    if (error instanceof TypeError) {
      return errorResponse(
        400,
        'INVALID_FORM_DATA',
        '파일 업로드 요청 형식이 올바르지 않습니다.',
        [{ path: 'file', message: error.message }],
      );
    }

    console.error('POST /api/activities/import failed:', error);
    return errorResponse(500, 'STORAGE_ERROR', '검증은 완료되었지만 서버에 activity.json을 저장하지 못했습니다.');
  }
}
'use client';

import { ChangeEvent, DragEvent, useRef, useState } from 'react';
import { AlertCircle, CheckCircle2, Download, FileJson, Loader2, Upload } from 'lucide-react';
import type { ActivitiesData } from '@/lib/types';

const MAX_FILE_SIZE = 2 * 1024 * 1024;

interface ValidationIssue {
  path: string;
  message: string;
}

interface ImportFeedback {
  kind: 'success' | 'error';
  title: string;
  details?: ValidationIssue[];
}

interface ImportResponse {
  success?: boolean;
  error?: string;
  details?: ValidationIssue[];
  importedCount?: number;
  normalizedLegacyStatuses?: number;
  data?: ActivitiesData;
}

interface Props {
  currentData?: ActivitiesData;
  onImported: (data: ActivitiesData) => void;
  onUnauthorized: () => void;
}

function formatFileSize(size: number) {
  if (size < 1024) return `${size} B`;
  return `${(size / 1024).toFixed(1)} KB`;
}

export default function ActivityJsonImporter({ currentData, onImported, onUnauthorized }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewCount, setPreviewCount] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [feedback, setFeedback] = useState<ImportFeedback | null>(null);
  const canUpload = Boolean(
    selectedFile
    && selectedFile.size > 0
    && selectedFile.size <= MAX_FILE_SIZE
    && selectedFile.name.toLowerCase().endsWith('.json'),
  );

  const inspectFile = async (file: File) => {
    setSelectedFile(file);
    setPreviewCount(null);
    setFeedback(null);

    if (!file.name.toLowerCase().endsWith('.json')) {
      setFeedback({
        kind: 'error',
        title: 'JSON 파일만 선택할 수 있습니다.',
        details: [{ path: 'file', message: `선택한 파일명: ${file.name}` }],
      });
      return;
    }

    if (file.size === 0 || file.size > MAX_FILE_SIZE) {
      setFeedback({
        kind: 'error',
        title: file.size === 0 ? '선택한 파일이 비어 있습니다.' : '파일 크기는 2MB 이하여야 합니다.',
        details: [{ path: 'file', message: `현재 파일 크기: ${formatFileSize(file.size)}` }],
      });
      return;
    }

    try {
      const parsed: unknown = JSON.parse((await file.text()).replace(/^\uFEFF/, ''));
      if (
        typeof parsed === 'object'
        && parsed !== null
        && !Array.isArray(parsed)
        && Array.isArray((parsed as Record<string, unknown>).activities)
      ) {
        setPreviewCount(((parsed as Record<string, unknown>).activities as unknown[]).length);
      }
    } catch {
      // 서버가 행/열 정보를 포함한 상세 JSON 문법 오류를 반환하도록 업로드는 허용합니다.
    }
  };

  const handleFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) void inspectFile(file);
  };

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragging(false);
    const file = event.dataTransfer.files?.[0];
    if (file) void inspectFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setFeedback({ kind: 'error', title: '업로드할 activity.json 파일을 선택해 주세요.' });
      return;
    }
    if (selectedFile.size === 0 || selectedFile.size > MAX_FILE_SIZE || !selectedFile.name.toLowerCase().endsWith('.json')) {
      return;
    }

    const countLabel = previewCount === null ? '파일의 데이터' : `${previewCount.toLocaleString('ko-KR')}개 액티비티`;
    if (!window.confirm(`${countLabel}로 현재 상황판을 교체하시겠습니까?\n교체 직전 데이터는 서버에 백업됩니다.`)) {
      return;
    }

    setIsUploading(true);
    setFeedback(null);

    try {
      const formData = new FormData();
      formData.append('file', selectedFile);
      const response = await fetch('/api/activities/import', { method: 'POST', body: formData });
      const result = await response.json().catch(() => ({
        error: `서버 응답을 해석하지 못했습니다. (HTTP ${response.status})`,
      })) as ImportResponse;

      if (!response.ok || !result.data) {
        setFeedback({
          kind: 'error',
          title: result.error ?? `업로드에 실패했습니다. (HTTP ${response.status})`,
          details: result.details,
        });
        if (response.status === 401) onUnauthorized();
        return;
      }

      onImported(result.data);
      const normalizedMessage = result.normalizedLegacyStatuses
        ? ` · 기존 상태값 '진행중' ${result.normalizedLegacyStatuses}건을 '진행'으로 변환했습니다.`
        : '';
      setFeedback({
        kind: 'success',
        title: `${(result.importedCount ?? result.data.activities.length).toLocaleString('ko-KR')}개 액티비티를 반영했습니다.${normalizedMessage}`,
      });
      setSelectedFile(null);
      setPreviewCount(null);
      if (inputRef.current) inputRef.current.value = '';
    } catch (error) {
      setFeedback({
        kind: 'error',
        title: '서버에 연결하지 못해 업로드에 실패했습니다.',
        details: [{ path: 'network', message: error instanceof Error ? error.message : '알 수 없는 네트워크 오류' }],
      });
    } finally {
      setIsUploading(false);
    }
  };

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { Activity } from './types.ts';
import { collectDescendantIds, deleteActivity, initialActivities } from './treeUtils.ts';

function node(id: string, parentId: string | null, level = parentId ? 2 : 1): Activity {
  return { id, parentId, level, time: '미정', title: id, status: '대기' };
}

// 업로드한 activity.json 처럼 id 가 `부모-번호` 꼴이 아닌 3단 트리
const arbitraryTree: Activity[] = [
  node('net', null),
  node('vlan', 'net'),
  node('vlan-check', 'vlan', 3),
  node('db', null),
  node('dbswitch', 'db'),
];

describe('collectDescendantIds', () => {
  it('parentId 관계를 따라 대상과 모든 하위를 모은다', () => {
    assert.deepEqual([...collectDescendantIds(arbitraryTree, 'net')].sort(), ['net', 'vlan', 'vlan-check']);
  });

  it('없는 id 는 자기 자신만 돌려준다', () => {
    assert.deepEqual([...collectDescendantIds(arbitraryTree, 'ghost')], ['ghost']);
  });

  it('parentId 가 순환해도 무한루프 없이 끝난다', () => {
    const cyclic: Activity[] = [node('a', 'b'), node('b', 'a'), node('c', 'a')];
    assert.deepEqual([...collectDescendantIds(cyclic, 'a')].sort(), ['a', 'b', 'c']);
  });
});

describe('deleteActivity', () => {
  it('초기 데이터에서 "2" 를 지우면 2 와 2-1~2-4 만 빠지고 나머지 15개는 남는다', () => {
    const remaining = deleteActivity(initialActivities, '2');
    assert.equal(remaining.length, initialActivities.length - 5);
    assert.deepEqual(
      remaining.map((activity) => activity.id),
      initialActivities.map((activity) => activity.id).filter((id) => id !== '2' && !id.startsWith('2-')),
    );
  });

  it('id 접두사가 다른 임의 id 트리에서도 parentId 관계로 3단 하위까지 지운다', () => {
    const remaining = deleteActivity(arbitraryTree, 'net');
    assert.deepEqual(remaining.map((activity) => activity.id), ['db', 'dbswitch']);
  });

  it('id 가 "1-" 로 시작해도 parentId 가 다르면 "1" 삭제 때 남는다', () => {
    const activities: Activity[] = [node('1', null), node('1-1', '1'), node('2', null), node('1-x', '2')];
    const remaining = deleteActivity(activities, '1');
    assert.deepEqual(remaining.map((activity) => activity.id), ['2', '1-x']);
  });

  it('없는 id 를 지우면 아무것도 바뀌지 않는다', () => {
    assert.deepEqual(deleteActivity(arbitraryTree, 'ghost'), arbitraryTree);
  });
});
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { Activity } from './types.ts';
import {
  ActivityImportValidationError,
  validateActivityImport,
  type ImportValidationIssue,
} from './activityData.ts';

// 라우트가 JSON.parse 로 만들어 넘기는 것과 같은 평문 객체를 그대로 쓴다(모킹 없음).
function raw(overrides: Partial<Record<keyof Activity, unknown>>): Record<string, unknown> {
  return { id: 'a', parentId: null, level: 1, time: '09:00', title: '작업', status: '대기', ...overrides };
}

function issuesOf(value: unknown): ImportValidationIssue[] {
  try {
    validateActivityImport(value);
  } catch (error) {
    if (!(error instanceof ActivityImportValidationError)) throw error;
    return error.issues;
  }
  return assert.fail('ActivityImportValidationError 가 발생해야 합니다.');
}

describe('validateActivityImport 정상 입력', () => {
  it('최상위와 자식 2건을 통과시키고 id·parentId 의 앞뒤 공백을 trim 한다', () => {
    const result = validateActivityImport({
      activities: [
        raw({ id: '  root  ', parentId: null, level: 1 }),
        raw({ id: '  child  ', parentId: '  root  ', level: 2 }),
      ],
    });

    assert.equal(result.activities.length, 2);
    assert.deepEqual(result.activities.map((activity) => activity.id), ['root', 'child']);
    assert.equal(result.activities[1].parentId, 'root');
  });

  it('dashboardTitle 의 앞뒤 공백을 trim 해서 돌려준다', () => {
    const result = validateActivityImport({
      activities: [raw({})],
      dashboardTitle: '  제목  ',
    });

    assert.equal(result.dashboardTitle, '제목');
  });

  it('dashboardTitle 을 주지 않으면 undefined 를 돌려준다', () => {
    const result = validateActivityImport({ activities: [raw({})] });

    assert.equal(result.dashboardTitle, undefined);
  });

  it('빈 activities 배열은 throw 하지 않고 빈 배열을 돌려준다', () => {
    // 관리 화면의 "최상위 작업 추가" 진입점이 이 계약에 의존한다.
    const result = validateActivityImport({ activities: [] });

    assert.deepEqual(result.activities, []);
  });
});

describe('validateActivityImport 최상위 형식 오류', () => {
  for (const [label, value] of [
    ['배열', [] as unknown],
    ['문자열', 'x' as unknown],
    ['null', null as unknown],
  ] as const) {
    it(`최상위 값이 객체가 아니면(${label}) path '$' 오류 1건으로 throw 한다`, () => {
      const issues = issuesOf(value);

      assert.equal(issues.length, 1);
      assert.equal(issues[0].path, '$');
    });
  }

  it("activities 가 배열이 아니면 path 'activities' 오류 1건으로 throw 한다", () => {
    const issues = issuesOf({ activities: 'x' });

    assert.equal(issues.length, 1);
    assert.equal(issues[0].path, 'activities');
  });
